const KITCH_OFFICE_EMBED='';
let kitchOfficeDecodePromise=null;
function prepareKitchOffice(){
 if(kitchOfficeDecodePromise)return kitchOfficeDecodePromise;
 kitchOfficeDecodePromise=new Promise((resolve,reject)=>{
  const work=()=>{try{const binary=atob(KITCH_OFFICE_EMBED);const bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);resolve(new TextDecoder().decode(bytes))}catch(e){kitchOfficeDecodePromise=null;reject(e)}};
  if('requestIdleCallback' in window)requestIdleCallback(work,{timeout:1200});else setTimeout(work,0);
 });return kitchOfficeDecodePromise;
}
function openKitchMainOffice(){
 const box=document.getElementById('kitchOfficeOverlay'),frame=document.getElementById('kitchOfficeFrame');
 box.classList.add('open');document.body.style.overflow='hidden';
 if(frame.dataset.initialized==='yes')return;
 if(frame.dataset.initialized==='loading')return;
 frame.dataset.initialized='loading';frame.classList.remove('ready');
 prepareKitchOffice().then(html=>{
  // Unified Master has one import entry point in Operations Inventory.
  // Preserve the embedded office code and hide legacy duplicate controls.
  html=html.replace('id="officeSupplierSync" type="button"','id="officeSupplierSync" type="button" hidden')
    .replace('label class="btn" style="cursor:pointer">Import Excel / CSV','label class="btn" style="display:none">Import Excel / CSV')
    .replace(".eq('restaurant_id',officeRid).order('name');\n if(error){ig('officeIngredientCount')",".eq('restaurant_id',officeRid).eq('is_active',true).eq('is_current_master',true).order('name');\n if(error){ig('officeIngredientCount')");
  html=kitchOfficeApplyChatNavigation(html);
  frame.srcdoc=html;frame.dataset.initialized='yes'
}).catch(e=>{
  console.error('Main Office loading failed',e);frame.dataset.initialized='';
  document.getElementById('kitchOfficeLoading').textContent='Unable to load Main Office. Please refresh and try again.';
 });
}
function closeKitchMainOffice(){document.getElementById('kitchOfficeOverlay').classList.remove('open');document.body.style.overflow='';document.getElementById('login')?.classList.remove('hidden')}
window.addEventListener('message',function(event){
  const frame=document.getElementById('kitchOfficeFrame');
  if(!frame||event.source!==frame.contentWindow||event.data?.type!=='KITCH_OFFICE_SIGNED_OUT')return;
  closeKitchMainOffice();
  // The cached office has already reset its signed-out view.
  // Its own Supabase auth listener controls the signed-out view.
  try{session=null;currentStaff=null;teamCloudAuth=null;cloud={restaurant_id:null,branch_id:null,workspace_code:null,user:null};}catch(e){}
  try{
    document.getElementById('app')?.classList.add('hidden');
    document.getElementById('login')?.classList.remove('hidden');
    document.body.style.overflow='';
    document.documentElement.classList.remove('modal-open');
    document.body.classList.remove('modal-open');
  }catch(e){}
  try{closePublicModal();}catch(e){}
  window.scrollTo(0,0);
});



function kitchOfficeApplyChatNavigation(html){
 if(!html.includes('<main class="content">')||!html.includes('</head>')||!html.includes('</body>'))return html;
 const css="\n/* KITCH Main Office navigation: independent of kitchen staff workspace */\n#officeApp.frame{max-width:none!important;width:100%!important;margin:0!important;padding:0!important}\n#officeApp .app{display:grid!important;grid-template-columns:246px minmax(0,1fr)!important;border-radius:0!important;min-height:100dvh!important;overflow:visible!important;background:#f8f8f8!important;box-shadow:none!important}\n#officeApp .content{grid-column:2!important;min-width:0!important;padding:28px 30px!important}\n#officeApp .header{display:flex!important;gap:12px!important;justify-content:space-between!important;align-items:center!important;min-height:55px!important;border-bottom:1px solid #ececec!important;padding:0 0 15px!important}\n#officeApp .header .topnav{display:none!important}\n#officeApp .officeChatSidebar{grid-column:1;position:sticky;top:0;height:100dvh;min-height:0;background:#f7f7f7;border-right:1px solid #e7e7e7;display:flex;flex-direction:column;box-sizing:border-box;padding:18px 12px;gap:12px;overflow:hidden}\n#officeApp .officeChatBrand{display:flex;align-items:center;gap:8px;flex:0 0 auto;min-height:54px;border-bottom:1px solid #e5e5e5;padding:0 7px 12px;color:#151515;font-size:23px;font-weight:900;letter-spacing:-.05em}\n#officeApp .officeChatBrand small{font-size:10px;font-weight:750;letter-spacing:.02em;color:#929292}\n#officeApp .officeChatNav{display:flex;flex-direction:column;gap:4px;flex:1 1 auto;min-height:0;overflow:auto;overscroll-behavior:contain;-webkit-overflow-scrolling:touch;scrollbar-width:thin}\n#officeApp .officeChatNav button{width:100%;min-height:45px;display:flex;align-items:center;gap:11px;flex:0 0 auto;background:transparent;color:#272727;border:0;border-radius:12px;text-align:left;font-size:13px;font-weight:650;padding:9px 12px;white-space:normal}\n#officeApp .officeChatNav button.active,#officeApp .officeChatNav button:hover{background:#e9e9e9;color:#151515}\n#officeApp .officeChatNav .officeChatIcon{width:23px;font-size:18px;font-weight:700;display:inline-grid;place-items:center}\n#officeApp .officeChatFooter{flex:0 0 auto;border-top:1px solid #e4e4e4;padding:11px 0 0;display:flex;align-items:center;justify-content:space-between;gap:7px}\n#officeApp .officeChatFooter button{min-height:39px;border-radius:11px;background:#171717;color:#fff;padding:0 13px;font-size:12px;font-weight:800}\n#officeApp .officeChatMobileToggle,#officeApp .officeChatClose,#officeApp .officeChatBackdrop{display:none}\n@media(max-width:800px){\n #officeApp .app{display:block!important;grid-template-columns:none!important;min-height:100dvh!important}\n #officeApp .content{display:block!important;grid-column:auto!important;padding:17px 14px!important}\n #officeApp .header{display:flex!important;align-items:center!important;padding:3px 0 12px 57px!important;min-height:56px!important}\n #officeApp .header strong{font-size:19px!important;overflow-wrap:anywhere}\n #officeApp .officeChatMobileToggle{position:fixed;top:calc(14px + env(safe-area-inset-top,0px));left:14px;z-index:80;display:grid;place-items:center;width:42px;height:42px;padding:0;border:1px solid #ddd;border-radius:12px;background:#fff;color:#111;font-size:20px;box-shadow:0 3px 12px #0000000d}\n #officeApp .officeChatSidebar{position:fixed!important;inset:0 auto 0 0!important;grid-column:auto!important;z-index:90;width:min(340px,88vw)!important;max-width:88vw!important;height:100dvh!important;transform:translate3d(-105%,0,0)!important;transition:transform .24s cubic-bezier(.22,.8,.23,1)!important;padding:calc(14px + env(safe-area-inset-top,0px)) 14px calc(15px + env(safe-area-inset-bottom,0px))!important;box-shadow:5px 0 24px #00000010}\n #officeApp .app.officeChatOpen .officeChatSidebar{transform:translate3d(0,0,0)!important}\n #officeApp .officeChatBrand{padding-right:48px!important;position:relative}\n #officeApp .officeChatClose{position:absolute;right:4px;top:3px;display:grid;place-items:center;width:39px;height:39px;border:1px solid #ddd;border-radius:11px;background:#ededed;color:#222;font-size:26px}\n #officeApp .officeChatBackdrop{position:fixed;inset:0;background:#0006;z-index:85;display:none}\n #officeApp .app.officeChatOpen .officeChatBackdrop{display:block}\n #officeApp .hero{max-width:100%;flex-wrap:wrap}\n}\n@media(prefers-reduced-motion:reduce){#officeApp .officeChatSidebar{transition:none!important}}\n\n\n/* KITCH Olith-inspired neutral palette 2026-11-22: presentational only */\n:root{--bg:#dce2df!important;--panel:#fcfcfb!important;--ink:#273338!important;--muted:#89918f!important;--line:#e2e6e4!important;--orange:#718d8b!important}\nbody{background:#dce2df!important;color:#273338!important}\n#officeApp.frame{background:#e9edeb!important}\n#officeApp .app{background:#f2f4f3!important}\n#officeApp .officeChatSidebar{background:#e9edeb!important;border-right:1px solid #dfe5e2!important}\n#officeApp .officeChatBrand{border-color:#dfe5e2!important;color:#273338!important}\n#officeApp .officeChatBrand small{color:#939c99!important}\n#officeApp .officeChatNav button{color:#43504e!important;font-weight:600!important}\n#officeApp .officeChatNav button:hover,#officeApp .officeChatNav button.active{background:#dce2df!important;color:#23302e!important}\n#officeApp .officeChatNav .officeChatIcon{color:#607875!important}\n#officeApp .officeChatFooter{border-color:#dce2df!important}\n#officeApp .officeChatFooter button{background:#384b49!important;color:#fff!important}\n#officeApp .content{background:#f3f5f4!important}\n#officeApp .header{border-color:#e1e6e3!important}\n#officeApp .header strong{color:#2b3837!important}\n#officeApp .hero h1,#officeApp .titleline h2{color:#2a3737!important}\n#officeApp .hero p,#officeApp .subhead{color:#8a9491!important}\n#officeApp .card{background:#fcfdfc!important;border:1px solid #e2e8e4!important;border-radius:17px!important;box-shadow:0 1px 3px #1b323008!important;color:#2e3b39!important}\n#officeApp .card.featured{background:#e1e9e5!important;color:#293d39!important;border:1px solid #dae4df!important}\n#officeApp .card.featured small,#officeApp .card.featured .foot{color:#7c928b!important}\n#officeApp .card small,#officeApp .card .foot{color:#89928f!important}\n#officeApp .card .number{color:#2e3a39!important;font-weight:700!important}\n#officeApp .note{background:#e7ece9!important;color:#59716d!important;border:1px solid #dce4e0!important;border-radius:14px!important}\n#officeApp .tag,#officeApp .ghost{background:#fafbfa!important;border:1px solid #e2e8e4!important;color:#52605d!important}\n#officeApp .btn{background:#405651!important;color:#fff!important}\n#officeApp .bar{background:#90aba3!important}\n#officeApp .bar.grey{background:#526b66!important}\n#officeApp .dot{background:#90aba3!important}\n#officeApp .dot.dark{background:#526b66!important}\n#officeApp table th{background:#f4f6f5!important;color:#8b9692!important}\n#officeApp table td,#officeApp table th{border-color:#e7ece9!important}\n#officeApp .profile .avatar{background:#dce7e1!important;color:#536c63!important}\n#officeApp input,#officeApp select{border-color:#dce4df!important}\n#officeApp .section{min-width:0!important}\n@media(min-width:1100px){\n #officeApp .app{grid-template-columns:228px minmax(0,1fr)!important}\n #officeApp .officeChatSidebar{padding:22px 13px!important}\n #officeApp .content{padding:30px 32px!important}\n #officeApp .grid{gap:12px!important}\n}\n@media(max-width:800px){\n #officeApp .app{grid-template-columns:none!important}\n #officeApp .content{padding:17px 14px!important}\n #officeApp .officeChatSidebar{background:#edf0ee!important}\n #officeApp .officeChatMobileToggle{background:#fafcfb!important;border-color:#dce4df!important;color:#2c3d39!important}\n #officeApp .card{border-radius:17px!important}\n}\n";
 const markup="<button type=\"button\" class=\"officeChatMobileToggle\" aria-label=\"Open Main Office menu\">☰</button><div class=\"officeChatBackdrop\"></div><aside class=\"officeChatSidebar\" aria-label=\"Main Office sections\"><div class=\"officeChatBrand\">KITCH <small>/ MAIN OFFICE</small><button type=\"button\" class=\"officeChatClose\" aria-label=\"Close Main Office menu\">×</button></div><nav class=\"officeChatNav\" aria-label=\"Main Office navigation\"></nav><div class=\"officeChatFooter\"><span style=\"font-size:11px;color:#777\">Owner workspace</span><button type=\"button\" class=\"officeChatSignOut\">Sign Out</button></div></aside>";
 const script="\n(function(){\n const root=document.querySelector('#officeApp .app');\n if(!root||root.dataset.chatNavReady)return;root.dataset.chatNavReady='1';\n const pages=[['overview','Overview','⌂'],['ingredients','Ingredient Master','▦'],['purchasing','Purchasing','⇄'],['locations','Locations','▣'],['staff','Team','♙'],['reports','Reports','▥'],['settings','Account','⚙']];\n const nav=root.querySelector('.officeChatNav'),toggle=root.querySelector('.officeChatMobileToggle'),close=root.querySelector('.officeChatClose'),backdrop=root.querySelector('.officeChatBackdrop');\n function hideMenu(){root.classList.remove('officeChatOpen');toggle.setAttribute('aria-expanded','false')}\n function gotoPage(page){if(typeof showPage==='function')showPage(page);else document.querySelector('.topnav [data-page=\"'+page+'\"]')?.click();nav.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.target===page));hideMenu();}\n for(const [page,label,icon] of pages){\n  const b=document.createElement('button');b.type='button';b.dataset.target=page;\n  const symbol=document.createElement('span');symbol.className='officeChatIcon';symbol.textContent=icon;\n  const txt=document.createElement('span');txt.textContent=label;b.append(symbol,txt);\n  b.addEventListener('click',()=>gotoPage(page));nav.appendChild(b);\n }\n toggle.setAttribute('aria-expanded','false');toggle.addEventListener('click',()=>{const next=!root.classList.contains('officeChatOpen');root.classList.toggle('officeChatOpen',next);toggle.setAttribute('aria-expanded',String(next))});\n close.addEventListener('click',hideMenu);backdrop.addEventListener('click',hideMenu);\n document.addEventListener('keydown',e=>{if(e.key==='Escape')hideMenu()});\n root.querySelector('.officeChatSignOut').addEventListener('click',()=>{\n  const signOut=document.querySelector('#officeApp .officeLogout');\n  if(signOut)signOut.click();else alert('Owner sign out is not available yet.');\n });\n const active=document.querySelector('.section.active')?.id||'overview';\n nav.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.target===active));\n})();\n";
 return html.replace('</head>','<style id="kitch-office-chat-sidebar">'+css+'</style></head>')
   .replace('<main class="content">',markup+'<main class="content">')
   .replace('</body>','<script>'+script+'</script></body>');
}
